const c = JSON.parse(require('fs').readFileSync('combined_30.json'));
function parseEntry(item, i) {
  const text = item.text;
  const lines = text.split('\n');
  // find property type + name lines: they follow badges like 'Guest favorite', 'Superhost', or date range lines
  // Find line matching pattern 'X in Y' (property type in location)
  let typeLocIdx = lines.findIndex(l => / in /.test(l) && !l.includes('for') && !l.includes('night'));
  let typeLoc = lines[typeLocIdx] || '';
  let name = lines[typeLocIdx+1] || '';
  // beds/baths info
  const bedroomsMatch = text.match(/(\d+) bedrooms?/);
  const bedsMatch = text.match(/(\d+) beds?\b/);
  const bathsMatch = text.match(/([\d.]+) baths?/);
  const priceMatch = text.match(/\\$([\d,]+)\s*\\n?\s*\\$?([\d,]*)/);
  const ratingMatch = text.match(/([\d.]+) out of 5 average rating, (\d+) reviews/);
  const nightsMatch = text.match(/for (\d+) nights/);
  const dateRangeMatch = text.match(/([A-Za-z]{3} \d+)\s*to\s*([A-Za-z]{0,3}\s?\d+)/);
  const isGuestFav = /Guest favorite/.test(text);
  const isSuperhost = /Superhost/.test(text);
  const cleanUrl = 'https://www.airbnb.com' + item.href.split('?')[0];
  return {
    num: i+1,
    typeLoc,
    name,
    bedrooms: bedroomsMatch ? bedroomsMatch[1] : null,
    beds: bedsMatch ? bedsMatch[1] : null,
    baths: bathsMatch ? bathsMatch[1] : null,
    rating: ratingMatch ? ratingMatch[1] : null,
    reviews: ratingMatch ? ratingMatch[2] : null,
    nights: nightsMatch ? nightsMatch[1] : null,
    dateRange: dateRangeMatch ? (dateRangeMatch[1] + ' to ' + dateRangeMatch[2]) : null,
    guestFavorite: isGuestFav,
    superhost: isSuperhost,
    url: cleanUrl,
    rawText: text
  };
}
const parsed = c.map(parseEntry);
require('fs').writeFileSync('parsed_30.json', JSON.stringify(parsed, null, 2));
parsed.forEach(p => console.log(p.num, '|', p.typeLoc, '|', p.name, '| beds:', p.bedrooms, p.beds, p.baths, '| rating:', p.rating, p.reviews, '| nights:', p.nights, p.dateRange, '| url:', p.url));
"

