const c = JSON.parse(require('fs').readFileSync('parsed_30.json'));
c.forEach(p => {
  // final total price = last price in the prices array (discounted/final)
  p.finalPrice = p.prices.length ? p.prices[p.prices.length-1] : null;
  p.strikePrice = p.prices.length > 1 ? p.prices[0] : null;
  // clean type/loc into propType and location
  const m = p.typeLoc.match(/^(.*?) in (.*)$/);
  p.propType = m ? m[1] : p.typeLoc;
  p.location = m ? m[2] : '';
});
require('fs').writeFileSync('parsed_30.json', JSON.stringify(c, null, 2));
console.log('done');
"

